		repository.setFederatedServiceResolver(resolver);

		String independentArm = "{ SERVICE <urn:fail:independent> { ?r ?rp ?ro } }";
		String correlatedArm = "{ SERVICE <urn:fail:correlated> { ?x ?xp ?xo } }";
		String union = independentFirst
				? independentArm + " UNION " + correlatedArm
				: correlatedArm + " UNION " + independentArm;
		String operator = optional ? "OPTIONAL { " + union + " }" : "{ " + union + " }";
		String query = "SELECT * WHERE { VALUES ?x { } " + operator + " }";

		assertThrows(QueryEvaluationException.class, () -> evaluate(query));
		assertEquals(1, resolver.independentInvocations.get(),
				"the independent fatal SERVICE must be reached even with an empty left input");
