	private static final class FailingServiceResolver implements FederatedServiceResolver {

		@Override
		public FederatedService getService(String serviceUrl) {
			return new FailingService();
		}
	}

	/**
	 * Always-failing service. Mirrors real vectored services: {@link #evaluate} makes no "remote request" when the
	 * input binding stream is empty, and handles SILENT itself as the vectored contract requires (a failed SILENT
	 * invocation evaluates to the singleton empty mapping, so the input bindings pass through unchanged).
	 */
	private static class FailingService implements FederatedService {

		private boolean initialized;

		@Override
		public boolean ask(Service service, BindingSet bindings, String baseUri) {
			throw new QueryEvaluationException("service unavailable");
		}

		@Override
		public CloseableIteration<BindingSet> select(Service service, Set<String> projectionVars,
				BindingSet bindings, String baseUri) {
			throw new QueryEvaluationException("service unavailable");
		}

		@Override
		public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> bindings,
				String baseUri) {
			if (!bindings.hasNext()) {
				bindings.close();
				return new EmptyIteration<>();
			}
			if (service.isSilent()) {
				return bindings;
			}
			bindings.close();
			throw new QueryEvaluationException("service unavailable");
		}

		@Override
		public boolean isInitialized() {
			return initialized;
		}

		@Override
		public void initialize() {
			initialized = true;
		}

		@Override
		public void shutdown() {
			initialized = false;
		}
	}

	private static final class CountingFailingServiceResolver implements FederatedServiceResolver {

		private final AtomicInteger independentInvocations = new AtomicInteger();
		private final AtomicInteger correlatedInvocations = new AtomicInteger();
		private final AtomicInteger nestedIndependentInvocations = new AtomicInteger();
		private final AtomicInteger nestedCorrelatedInvocations = new AtomicInteger();
		private final AtomicReference<BindingSet> nestedIndependentBindings = new AtomicReference<>();
		private final AtomicReference<BindingSet> nestedCorrelatedBindings = new AtomicReference<>();

		@Override
		public FederatedService getService(String serviceUrl) {
			if ("urn:fail:independent".equals(serviceUrl)) {
				return new CountingFailingService(independentInvocations);
			}
			if ("urn:fail:correlated".equals(serviceUrl)) {
				return new CountingFailingService(correlatedInvocations);
			}
			if ("urn:fail:nested-independent".equals(serviceUrl)) {
				return new CountingFailingService(nestedIndependentInvocations, nestedIndependentBindings);
			}
			if ("urn:fail:nested-correlated".equals(serviceUrl)) {
				return new CountingFailingService(nestedCorrelatedInvocations, nestedCorrelatedBindings);
			}
			throw new AssertionError("unexpected SERVICE endpoint: " + serviceUrl);
		}
	}

	private static final class CountingFailingService extends FailingService {

		private final AtomicInteger invocations;
		private final AtomicReference<BindingSet> observedBindings;

		private CountingFailingService(AtomicInteger invocations) {
			this(invocations, null);
		}

		private CountingFailingService(AtomicInteger invocations, AtomicReference<BindingSet> observedBindings) {
			this.invocations = invocations;
			this.observedBindings = observedBindings;
		}

		@Override
		public boolean ask(Service service, BindingSet bindings, String baseUri) {
			invocations.incrementAndGet();
			throw new QueryEvaluationException("service unavailable");
		}

		@Override
		public CloseableIteration<BindingSet> select(Service service, Set<String> projectionVars,
				BindingSet bindings, String baseUri) {
			invocations.incrementAndGet();
			if (observedBindings != null) {
				observedBindings.set(new QueryBindingSet(bindings));
			}
			throw new QueryEvaluationException("service unavailable");
		}

		@Override
		public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> bindings,
				String baseUri) {
			if (!bindings.hasNext()) {
				bindings.close();
				return new EmptyIteration<>();
			}
			invocations.incrementAndGet();
			if (service.isSilent()) {
				return bindings;
			}
			if (observedBindings != null) {
				observedBindings.set(new QueryBindingSet(bindings.next()));
			}
			bindings.close();
			throw new QueryEvaluationException("service unavailable");
		}
	}

	private static final class RecordingServiceResolver implements FederatedServiceResolver {

		private final RecordingService service = new RecordingService();

		@Override
		public FederatedService getService(String serviceUrl) {
			if (!"urn:recording".equals(serviceUrl)) {
				throw new AssertionError("unexpected SERVICE endpoint: " + serviceUrl);
			}
			return service;
		}
	}

	private static final class RecordingService extends FailingService {

		private final AtomicInteger invocations = new AtomicInteger();
		private final AtomicReference<BindingSet> observedBindings = new AtomicReference<>();

		@Override
		public CloseableIteration<BindingSet> select(Service service, Set<String> projectionVars,
				BindingSet bindings, String baseUri) {
			invocations.incrementAndGet();
			QueryBindingSet result = new QueryBindingSet(bindings);
			observedBindings.set(new QueryBindingSet(bindings));
			result.setBinding("xo", SimpleValueFactory.getInstance().createIRI("urn:test:remote-object"));
			return new CloseableIteratorIteration<>(List.of(result).iterator());
		}

		@Override
		public CloseableIteration<BindingSet> evaluate(Service service, CloseableIteration<BindingSet> bindings,
				String baseUri) {
			invocations.incrementAndGet();
			List<BindingSet> results = new ArrayList<>();
			try {
				while (bindings.hasNext()) {
					QueryBindingSet result = new QueryBindingSet(bindings.next());
					observedBindings.compareAndSet(null, new QueryBindingSet(result));
					result.setBinding("xo", SimpleValueFactory.getInstance().createIRI("urn:test:remote-object"));
					results.add(result);
				}
			} finally {
				bindings.close();
			}
			return new CloseableIteratorIteration<>(results.iterator());
		}
	}

	private static final class OptionalProbeServiceResolver implements FederatedServiceResolver {

		private final AtomicReference<BindingSet> observedBindings;

		private OptionalProbeServiceResolver(AtomicReference<BindingSet> observedBindings) {
			this.observedBindings = observedBindings;
		}

		@Override
		public FederatedService getService(String serviceUrl) {
			return new OptionalProbeService(observedBindings);
		}
	}

	private static final class OptionalProbeService extends FailingService {

		private final AtomicReference<BindingSet> observedBindings;

		private OptionalProbeService(AtomicReference<BindingSet> observedBindings) {
			this.observedBindings = observedBindings;
		}

		@Override
		public boolean ask(Service service, BindingSet bindings, String baseUri) {
			observedBindings.set(new QueryBindingSet(bindings));
			if (bindings.hasBinding("optionalOnly")) {
				return false;
			}
			throw new QueryEvaluationException("service unavailable without optional entry binding");
		}

		@Override
		public CloseableIteration<BindingSet> select(Service service, Set<String> projectionVars,
				BindingSet bindings, String baseUri) {
			observedBindings.set(new QueryBindingSet(bindings));
			if (bindings.hasBinding("optionalOnly")) {
				return new EmptyIteration<>();
			}
			throw new QueryEvaluationException("service unavailable without optional entry binding");
		}
	}
